  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "In a rabbit meningitis model, intravenously administered oritavancin showed only 1–5% penetration into cerebrospinal fluid, indicating poor CNS access under the relevant condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "In rabbits, [14C]dalbavancin-derived radioactivity in CSF was very low and measurable only at late time points, consistent with limited blood-brain barrier penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "In a rabbit Streptococcus pneumoniae meningitis model, daptomycin reached only about 5% of the corresponding serum concentration in CSF, demonstrating poor CNS penetration after systemic administration.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Close structural analogs with direct meningitis-model CSF penetration data consistently show low CNS access, supporting a fail prediction for meaningful CNS exposure.",
  "evidence_gaps": [
    "No direct experimental data for the query molecule itself; inference relies on structurally similar antibiotics.",
    "Most direct evidence comes from rabbit meningitis models, with limited human CSF data.",
    "Positive BBB permeation evidence from low-similarity natural products is not condition-matched and does not outweigh direct meningitis CSF penetration results."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

